"""v0.121: visual (claro como padrão, cores com significado, 3D), Dashboard em camadas, nova campanha em 3 etapas,
campanha em rascunho, formulário de campanha em blocos, Growth Model com "Mais ações" e árvore "Por vendedor".
Banco fa (PostgREST 3300) + migração 20261023100000_arvore_vendedor.sql."""
import sys, json, subprocess; sys.path.insert(0, '.')
import front
from playwright.sync_api import sync_playwright
WS = 'ac56e719-7325-4062-aa47-74bc2141f89d'
PROD = '5a1c6077-dda8-42cf-9c96-ca913be007d2'
def sql(q):
    r = subprocess.run(['psql', '-h', '/var/run/postgresql', '-p', '55432', '-U', 'postgres', '-d', 'fa', '-Atq', '-v', 'ON_ERROR_STOP=1', '-c', q], capture_output=True, text=True)
    if r.returncode: raise Exception(r.stderr)
    return r.stdout.strip()
falhas = []
def chk(c, msg):
    print(('ok   ' if c else 'FALHA ') + msg)
    if not c: falhas.append(msg)
def limpa():
    sql(f"""delete from campanha_canais where campanha_id in (select id from campanhas where workspace_id = '{WS}' and nome like 'T121 %');
      delete from projetos where campanha_id in (select id from campanhas where workspace_id = '{WS}' and nome like 'T121 %');
      delete from campanhas where workspace_id = '{WS}' and nome like 'T121 %';""")
limpa()
chk(sql("select count(*) from pg_proc where proname = '_arv_vendas' and prosrc like '%e.id = z.vendedor_id%'") == '1', 'árvore: "Por vendedor" liga a venda à pessoa da equipe (equipe.id)')
with sync_playwright() as p:
    b = p.chromium.launch()
    ctx, pg = front.abre(b, hoje='2026-10-15', vw=1600, vh=1000)
    erros = []; pg.on('pageerror', lambda e: erros.append(str(e)))
    # ---------------- tema ----------------
    chk(pg.evaluate("() => document.documentElement.getAttribute('data-theme')") == 'light', 'modo claro é o padrão (sem escolha guardada)')
    pg.evaluate("() => trocaTema()")
    chk(pg.evaluate("() => localStorage.getItem('growths_tema')") == 'dark' and pg.evaluate("() => document.documentElement.getAttribute('data-theme')") is None, 'botão troca para o escuro e guarda a escolha')
    pg.evaluate("() => trocaTema()")
    # ---------------- Dashboard ----------------
    t = front.vai(pg, 'adm-painel', "S.pg = { per: '30d' }", 5000)
    rot = pg.evaluate("() => [...document.querySelectorAll('.kpis.hero .kpi .l')].map(x => x.textContent.replace(/[ⓘ⚠›\\s]+$/u, '').trim())")
    chk(rot == ['Receita bruta das vendas', 'Lucro', 'Saldo em banco', 'CAC total'], 'O que importa agora: 4 cartões grandes ' + str(rot))
    chk(pg.locator('.kpis.mini .kpi').count() == 8, 'Funil, vendas e contas: 8 cartões menores')
    chk(pg.locator('.kpis.hero svg.spk').count() == 2, 'receita e lucro com a tendência por mês')
    fin = pg.evaluate("() => [...document.querySelectorAll('.panel')].find(p => /Métricas financeiras/.test(p.querySelector('h2')?.textContent || ''))?.innerText || ''")
    chk('ROI' in fin and '\nLucro' not in fin, 'Métricas financeiras sem repetir o Lucro (está no alto)')
    luc = pg.evaluate("() => { const k = [...document.querySelectorAll('.kpis.hero .kpi')][1]; return [k.querySelector('.v').textContent, k.querySelector('.v').className] }")
    chk(('sem-v-desf' in luc[1]) == luc[0].strip().startswith(('-', '−')) and ('sem-v-fav' in luc[1] or 'sem-v-desf' in luc[1] or luc[0].strip() in ('R$ 0,00',)), 'lucro em verde se positivo e vermelho se negativo (v0.152: classes da camada semântica): ' + luc[0])
    chk(pg.locator('.kpis.hero .kpi.arvk').count() >= 2, 'cartões grandes de receita e lucro continuam abrindo a árvore')
    pg.click('#pgCacK'); pg.wait_for_timeout(900)
    chk(pg.evaluate("() => Math.abs(document.getElementById('pgCac').getBoundingClientRect().top) < 120"), 'cartão do CAC leva ao painel "CAC: o que é de mídia e o que é total"')
    mini = pg.evaluate("() => [...document.querySelectorAll('.kpis.mini .kpi .v')].map(v => [v.textContent, v.title])")
    chk(all(('mil' in v or 'mi' in v) == bool(tt) for v, tt in mini if v.startswith('R$')), 'valores de 10 mil para cima ficam compactos e o exato aparece no mouse')
    pg.evaluate("() => { const d = document.createElement('div'); d.className = 'kpis'; d.id = 'tNeg'; d.innerHTML = '<div class=\"kpi\"><span class=\"l\">Resultado no período</span><span class=\"v\">-R$ 1.234,00</span></div><div class=\"kpi\"><span class=\"l\">Margem</span><span class=\"v\">12,0%</span></div>'; document.querySelector('.main').appendChild(d); }")
    pg.wait_for_timeout(300)
    chk(pg.evaluate("() => { const k = document.querySelectorAll('#tNeg .kpi'); return k[0].querySelector('.v').classList.contains('sem-v-desf') && k[1].querySelector('.v').classList.contains('sem-v-fav') && k[0].querySelector('.v').textContent.startsWith('−'); }"), 'cartão de saldo: negativo em vermelho (com sinal de menos verdadeiro), positivo em verde (v0.153)')
    # ---------------- Nova campanha em etapas ----------------
    front.vai(pg, 'mkt-camp', "S.tabMkt = 'campanhas'; S.campSel = null", 3500)
    pg.click('#novaCamp'); pg.wait_for_timeout(1500)
    chk(pg.locator('#modalRoot .wz .wzp > div').count() == 3 and pg.locator('#modalRoot .wzp .at').inner_text().startswith('1.'), 'Nova campanha abre a etapa 1 de 3')
    pg.click('#modalRoot .wzf .pri'); pg.wait_for_timeout(800)
    chk('nome' in pg.inner_text('#toast').lower() or pg.locator('#modalRoot .wzp .at').inner_text().startswith('1.'), 'sem nome não avança')
    pg.fill('#modalRoot [name=nome]', 'T121 Black Friday'); pg.select_option('#modalRoot [name=produto_id]', PROD)
    pg.fill('#modalRoot [name=data_inicio]', '2026-11-01'); pg.fill('#modalRoot [name=data_fim]', '2026-11-30')
    pg.click('#modalRoot .wzf .pri'); pg.wait_for_timeout(2500)
    cid = sql(f"select id from campanhas where workspace_id = '{WS}' and nome = 'T121 Black Friday'")
    chk(bool(cid) and sql(f"select status from campanhas where id = '{cid}'") == 'rascunho', 'etapa 1 cria a campanha como rascunho')
    chk(pg.locator('#modalRoot .wzp .at').inner_text().startswith('2.'), 'vai para a etapa 2')
    pg.fill('#modalRoot [name=orcamento_total]', '25000'); pg.fill('#modalRoot [name=meta_vendas]', '120'); pg.fill('#modalRoot [name=meta_leads]', '4000'); pg.fill('#modalRoot [name=meta_cac]', '250')
    pg.wait_for_timeout(300); calc = pg.inner_text('#wzCalc').replace('\xa0', ' ')
    chk('R$ 6,25' in calc and '3,0%' in calc and 'R$ 208,33' in calc and 'R$ 119.640,00' in calc, 'etapa 2 calcula CPL, conversão, CAC e receita prevista')
    pg.click('#modalRoot .wzf .pri'); pg.wait_for_timeout(2500)
    chk(sql(f"select orcamento_total || '|' || meta_leads || '|' || meta_vendas || '|' || meta_cpl || '|' || meta_taxa_lead_venda from campanhas where id = '{cid}'") == '25000.00|4000|120|6.25|3.000', 'etapa 2 grava orçamento, metas, CPL e conversão')
    for k in ['meta_ads', 'google_ads', 'organico']: pg.click(f'#modalRoot [data-cn={k}]'); pg.wait_for_timeout(200)
    tot = pg.inner_text('#wzTab tr.tot')
    chk('100%' in tot and '4.000' in tot and '✓' in tot, 'etapa 3 sugere a divisão e confere o total: ' + tot.replace('\t', ' '))
    pg.fill('#wzTab input[data-p=meta_ads]', '60'); pg.dispatch_event('#wzTab input[data-p=meta_ads]', 'change'); pg.wait_for_timeout(300)
    chk('Sobram' not in pg.inner_text('#wzTab') and 'mais de 100%' in pg.inner_text('#wzTab'), 'avisa quando os canais passam de 100% do orçamento')
    pg.fill('#wzTab input[data-p=google_ads]', '30'); pg.dispatch_event('#wzTab input[data-p=google_ads]', 'change'); pg.wait_for_timeout(300)
    chk('Sobram 10%' in pg.inner_text('#wzTab'), 'avisa o orçamento que sobrou sem canal')
    pg.click('#modalRoot .wzf .pri'); pg.wait_for_timeout(4000)
    can = sql(f"select string_agg(canal || ':' || coalesce(orcamento::text, '-') || ':' || meta_leads || ':' || tipo || ':' || (utm_campaign <> ''), ',' order by canal) from campanha_canais where campanha_id = '{cid}'")
    chk(can == 'google_ads:7500.00:1800:pago:true,meta_ads:15000.00:1800:pago:true,organico:-:400:organico:true', 'etapa 3 grava os canais com orçamento, meta, tipo e utm: ' + can)
    chk(pg.evaluate("() => S.campSel") == cid and pg.locator('.rasc').count() == 1, 'ao concluir abre a campanha com a faixa de rascunho')
    chk(pg.evaluate("() => document.getElementById('cFechar').classList.contains('pri')") is False, 'rascunho: "Fechar a campanha" não fica em destaque')
    t = pg.inner_text('#main')
    chk('começa em 01/11/2026' in t and 'abaixo da meta' not in t, 'campanha que não começou mostra "começa em", não "abaixo da meta"')
    # rascunho sem metas: continuar abre a etapa certa
    sql(f"update campanhas set orcamento_total = null, meta_leads = null where id = '{cid}'"); front.vai(pg, 'mkt-camp', f"S.campSel = '{cid}'; S.campTab = 'resumo'", 3500)
    chk('○' in pg.evaluate("() => getComputedStyle(document.querySelector('.rasc li.p'), '::before').content") and pg.locator('.rasc [data-r=seg]').count() == 1, 'faixa mostra o que falta e "Continuar de onde parei"')
    pg.click('.rasc [data-r=seg]'); pg.wait_for_timeout(1500)
    chk(pg.locator('#modalRoot .wzp .at').inner_text().startswith('2.'), 'continuar abre direto a etapa que falta')
    pg.click('#modalRoot [data-w=depois]'); pg.wait_for_timeout(2500)
    chk(pg.locator('#modalRoot .wz').count() == 0 and pg.evaluate("() => S.campSel") == cid, '"Terminar depois" salva e volta para a campanha')
    # ---------------- Editar campanha em blocos ----------------
    pg.click('#cEd'); pg.wait_for_timeout(1200)
    chk(pg.locator('#modalRoot .fsec').count() == 4 and pg.locator('#modalRoot .dica').count() >= 4, 'editar campanha: 4 blocos e as explicações no ⓘ')
    vis = lambda n: pg.evaluate(f"() => document.querySelector('#modalRoot [name={n}]').closest('label').style.display !== 'none'")
    chk(vis('data_fim') and not vis('meta_leads_mes'), 'lançamento: mostra o fim e esconde a meta mensal do perpétuo')
    pg.select_option('#modalRoot [name=modelo]', 'perpetuo'); pg.wait_for_timeout(200)
    chk(not vis('data_fim') and vis('meta_leads_mes'), 'perpétuo: esconde o fim e o carrinho, mostra a meta por mês')
    pg.select_option('#modalRoot [name=modelo]', 'lancamento'); pg.fill('#modalRoot [name=nome]', 'T121 Black Friday 2')
    pg.focus('#modalRoot [name=nome]'); pg.keyboard.press('Control+s'); pg.wait_for_timeout(2500)
    chk(sql(f"select nome from campanhas where id = '{cid}'") == 'T121 Black Friday 2', 'Ctrl+S salva o formulário')
    # ---------------- Growth Model ----------------
    front.vai(pg, 'gro-modelo', '', 6000)
    chk(pg.evaluate("() => document.getElementById('gsNovo')?.classList.contains('pri') && !document.getElementById('gpCmp')?.classList.contains('pri')"), 'Growth Model: "Novo cenário" é a ação em destaque')
    chk(pg.locator('.maism.hide #gsLimpa').count() == 1, '"Limpar mudanças" e as outras ações ficam em "Mais ações"')
    pg.click('[data-mais]'); pg.wait_for_timeout(300)
    chk(pg.locator('.maism:not(.hide)').count() == 1, '"Mais ações" abre o menu')
    pg.mouse.click(1500, 900); pg.wait_for_timeout(300)
    chk(pg.locator('.maism:not(.hide)').count() == 0, 'clicar fora fecha o menu')
    chk(not erros, 'sem erro de JavaScript ' + str(erros[:3]))
    b.close()
limpa()
print('\n%d falha(s)' % len(falhas)); sys.exit(1 if falhas else 0)
